  return function curried(...args) {
    const done = args.length >= fn.length &&
      args.slice(0, fn.length).every((a) => a !== curry.placeholder);
    if (done) return fn.apply(this, args);
    return (...next) => {
      const merged = args.map((a) =>
        a === curry.placeholder && next.length ? next.shift() : a);
      return curried.apply(this, [...merged, ...next]);
    };
  };
}
curry.placeholder = Symbol('_');

