This runner drives a generator as a coroutine, the way libraries such as `co` did before `async/await`:

```js
function run(gen) {
  return new Promise((resolve, reject) => {
    const it = gen();
    function step(method, arg) {
      let r;
      try {
        r = it[method](arg);
      } catch (e) {
        return reject(e);
      }
      if (r.done) return resolve(r.value);
      Promise.resolve(r.value).then(
        (v) => step('next', v),
        (e) => step('throw', e),
      );
    }
    step('next');
  });
}
```

