A candidate writes a `jest.spyOn`-style helper. In an ES module, `counter.inc(2)` now throws `TypeError: Cannot read properties of undefined (reading 'n')`. What is the correct fix?

```js
function spyOn(obj, method) {
  const orig = obj[method];
  const spy = { calls: [] };
  obj[method] = (...args) => {
    spy.calls.push(args);
    return orig(...args);
  };
  return spy;
}

const counter = { n: 0, inc(by) { this.n += by; return this.n; } };
const spy = spyOn(counter, 'inc');
