```

An interviewer asks you to memoize a recursive Fibonacci. Two versions are written:

```js
// Version 1
function fib1(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n]) return memo[n];
  return (memo[n] = fib1(n - 1, memo) + fib1(n - 2, memo));
}

// Version 2
function fib2(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n]) return memo[n];
  return (memo[n] = fib2(n - 1) + fib2(n - 2));
}
```

